import { AssembleJS } from '@assemblejs/core';
import { ModuleFederation } from '@assemblejs/federation';

// Initialize AssembleJS with module federation
const app = new AssembleJS({
  name: 'shell-app',
  federation: {
    remotes: {
      header: 'header@https://cdn.example.com/header/remoteEntry.js',
      cart: 'cart@https://cdn.example.com/cart/remoteEntry.js',
      footer: 'footer@https://cdn.example.com/footer/remoteEntry.js'
    }
  }
});

// Load and render micro-frontends
const Header = await app.load('header');
const Cart = await app.load('cart');

// Seamlessly integrate different frameworks
app.render(<Header user={currentUser} />, '#header');
app.render(<Cart items={cartItems} />, '#cart');

import { Island, Archipelago } from '@assemblejs/islands';

// Define interactive islands in a sea of static content
export const ProductIsland = Island({
  name: 'product-details',
  hydration: 'lazy', // Only hydrate when visible
  priority: 'high',

  component: ({ product }) => {
    const [quantity, setQuantity] = useState(1);

    return (
      <div className="product-island">
        <h2>{product.name}</h2>
        <ProductImage lazy src={product.image} />
        <QuantitySelector 
          value={quantity}
          onChange={setQuantity}
        />
        <AddToCartButton 
          product={product}
          quantity={quantity}
        />
      </div>
    );
  }
});

// Orchestrate multiple islands
const archipelago = new Archipelago({
  islands: [ProductIsland, ReviewsIsland, RecommendationsIsland],
  strategy: 'progressive' // Hydrate based on user interaction
});

