const { FederationServer } = require('@assemblejs/server');
const { CDN } = require('@assemblejs/cdn');
const express = require('express');

const app = express();

// Configure module federation server
const federation = new FederationServer({
  name: 'federation-gateway',

  // Remote module registry
  remotes: {
    header: {
      url: process.env.HEADER_SERVICE_URL,
      fallback: './fallbacks/header.js',
      cache: { ttl: 3600, strategy: 'stale-while-revalidate' }
    },
    cart: {
      url: process.env.CART_SERVICE_URL,
      fallback: './fallbacks/cart.js',
      healthCheck: '/health'
    }
  },

  // Version management
  versioning: {
    strategy: 'semver',
    autoUpdate: true,
    rollback: true
  },

  // Performance optimization
  optimization: {
    preload: ['header', 'navigation'],
    lazy: ['cart', 'checkout'],
    compression: 'brotli'
  }
});

// CDN integration for edge deployment
const cdn = new CDN({
  provider: 'cloudflare',
  zones: ['us-east-1', 'eu-west-1', 'ap-south-1'],
  purgeOnDeploy: true
});

federation.pipe(cdn);

import { ApolloGateway, RemoteGraphQLDataSource } from '@apollo/gateway';
import { AssembleJSDataSource } from '@assemblejs/graphql';

// GraphQL Federation Gateway for micro-frontends
const gateway = new ApolloGateway({
  serviceList: [
    { name: 'products', url: 'http://products-api/graphql' },
    { name: 'users', url: 'http://users-api/graphql' },
    { name: 'cart', url: 'http://cart-api/graphql' },
    { name: 'inventory', url: 'http://inventory-api/graphql' }
  ],

  // Custom data source for AssembleJS integration
  buildService({ url }) {
    return new AssembleJSDataSource({
      url,

      // Automatic module loading based on GraphQL queries
      moduleLoader: {
        enabled: true,
        strategy: 'on-demand',
        cache: new RedisCache({ ttl: 300 })
      },

      // Performance tracing
      telemetry: {
        enabled: true,
        serviceName: 'assemblejs-gateway',
        includeQuery: true
      },

      // Error handling
      errorHandler: (error, service) => {
        if (error.extensions?.code === 'MODULE_NOT_FOUND') {
          // Fallback to default module
          return this.loadFallbackModule(service);
        }
        throw error;
      }
    });
  },

  // Query planning optimizations
  experimental_pollInterval: 10000,
  experimental_approximateQueryPlanStoreMiB: 50
});

