# AssembleJS Multi-Region Infrastructure

module "assemblejs_cluster" {
  source = "./modules/eks-assemblejs"

  cluster_name    = "assemblejs-production"
  cluster_version = "1.28"

  # Multi-AZ deployment for high availability
  subnet_ids = module.vpc.private_subnets

  node_groups = {
    # Shell application nodes
    shell = {
      desired_capacity = 3
      min_capacity     = 2
      max_capacity     = 10

      instance_types = ["t3.large"]

      labels = {
        app       = "assemblejs"
        component = "shell"
      }
    }

    # Micro-frontend nodes with GPU for rendering
    frontends = {
      desired_capacity = 5
      min_capacity     = 3
      max_capacity     = 20

      instance_types = ["g4dn.xlarge"]

      labels = {
        app          = "assemblejs"
        component    = "micro-frontend"
        gpu-enabled  = "true"
      }

      taints = [{
        key    = "gpu"
        value  = "true"
        effect = "NO_SCHEDULE"
      }]
    }
  }
}

# CDN Distribution for micro-frontends
resource "aws_cloudfront_distribution" "assemblejs_cdn" {
  enabled             = true
  is_ipv6_enabled     = true
  comment             = "AssembleJS Module Federation CDN"
  default_root_object = "remoteEntry.js"

  origin {
    domain_name = aws_s3_bucket.modules.bucket_regional_domain_name
    origin_id   = "S3-assemblejs-modules"

    s3_origin_config {
      origin_access_identity = aws_cloudfront_origin_access_identity.modules.cloudfront_access_identity_path
    }
  }

  default_cache_behavior {
    allowed_methods  = ["GET", "HEAD", "OPTIONS"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "S3-assemblejs-modules"

    forwarded_values {
      query_string = true
      headers      = ["X-Module-Version", "X-Island-Priority"]

      cookies {
        forward = "none"
      }
    }

    viewer_protocol_policy = "redirect-to-https"
    min_ttl                = 0
    default_ttl            = 3600
    max_ttl                = 86400
    compress               = true
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }
}

// Cloudflare Worker for AssembleJS Edge Runtime

addEventListener('fetch', event => {
  event.respondWith(handleRequest(event.request));
});

async function handleRequest(request) {
  const url = new URL(request.url);

  // Module Federation at the Edge
  if (url.pathname.startsWith('/modules/')) {
    return handleModuleRequest(request, url);
  }

  // Island Hydration Strategy
  if (url.pathname.startsWith('/islands/')) {
    return handleIslandRequest(request, url);
  }

  // Default shell application
  return handleShellRequest(request);
}

async function handleModuleRequest(request, url) {
  const moduleName = url.pathname.split('/')[2];
  const version = request.headers.get('X-Module-Version') || 'latest';

  // Check edge cache first
  const cacheKey = `module:${moduleName}:${version}`;
  const cachedModule = await MODULES.get(cacheKey);

  if (cachedModule) {
    return new Response(cachedModule, {
      headers: {
        'Content-Type': 'application/javascript',
        'Cache-Control': 'public, max-age=31536000, immutable',
        'X-Cache': 'HIT'
      }
    });
  }

  // Fetch from origin
  const moduleUrl = `${ORIGIN_URL}/modules/${moduleName}/${version}/remoteEntry.js`;
  const response = await fetch(moduleUrl);

  if (response.ok) {
    const moduleContent = await response.text();

    // Optimize at edge
    const optimized = await optimizeModule(moduleContent, {
      target: request.headers.get('User-Agent'),
      location: request.cf?.country || 'US'
    });

    // Store in edge cache
    await MODULES.put(cacheKey, optimized, {
      expirationTtl: 86400
    });

    return new Response(optimized, {
      headers: {
        'Content-Type': 'application/javascript',
        'Cache-Control': 'public, max-age=31536000, immutable',
        'X-Cache': 'MISS'
      }
    });
  }

  // Fallback
  return new Response('Module not found', { status: 404 });
}

async function handleIslandRequest(request, url) {
  const priority = request.headers.get('X-Island-Priority') || 'normal';

  // Adaptive hydration based on device and network
  const hydrationStrategy = determineHydrationStrategy({
    deviceType: request.headers.get('Sec-CH-UA-Mobile'),
    networkType: request.headers.get('RTT'),
    priority: priority
  });

  return new Response(JSON.stringify({
    strategy: hydrationStrategy,
    delay: hydrationStrategy === 'immediate' ? 0 : 1000
  }), {
    headers: { 'Content-Type': 'application/json' }
  });
}

