import { Telemetry } from '@assemblejs/telemetry';
import { PrometheusExporter } from '@opentelemetry/exporter-prometheus';
import { JaegerExporter } from '@opentelemetry/exporter-jaeger';

// Initialize AssembleJS telemetry
const telemetry = new Telemetry({
  serviceName: 'assemblejs-production',

  // Metrics collection
  metrics: {
    exporter: new PrometheusExporter({
      port: 9090,
      endpoint: '/metrics'
    }),

    // Custom metrics for module federation
    custom: [
      {
        name: 'module_load_duration',
        type: 'histogram',
        help: 'Time to load remote modules',
        labels: ['module', 'version', 'status']
      },
      {
        name: 'island_hydration_time',
        type: 'histogram',
        help: 'Time to hydrate islands',
        labels: ['island', 'strategy', 'priority']
      },
      {
        name: 'federation_cache_hit_rate',
        type: 'gauge',
        help: 'Module federation cache hit rate',
        labels: ['cache_type']
      }
    ]
  },

  // Distributed tracing
  tracing: {
    exporter: new JaegerExporter({
      endpoint: process.env.JAEGER_ENDPOINT,
      serviceName: 'assemblejs'
    }),

    // Automatic instrumentation
    instrumentations: [
      '@assemblejs/instrumentation-federation',
      '@assemblejs/instrumentation-islands',
      '@opentelemetry/instrumentation-http',
      '@opentelemetry/instrumentation-graphql'
    ],

    // Sampling strategy
    sampler: {
      type: 'adaptive',
      targetRate: 0.1,
      maxRate: 1.0,
      rules: [
        { path: '/health', sample: 0 },
        { path: '/modules/*', sample: 0.5 },
        { error: true, sample: 1.0 }
      ]
    }
  },

  // Real User Monitoring (RUM)
  rum: {
    enabled: true,
    endpoint: '/api/rum',

    // Track module performance
    moduleMetrics: {
      loadTime: true,
      renderTime: true,
      errorRate: true,
      bundleSize: true
    },

    // Track island metrics
    islandMetrics: {
      hydrationTime: true,
      interactionDelay: true,
      viewportVisibility: true
    }
  }
});

// Grafana dashboard configuration
export const dashboardConfig = {
  title: 'AssembleJS Production Metrics',
  panels: [
    {
      title: 'Module Load Performance',
      query: 'histogram_quantile(0.95, module_load_duration_bucket)',
      visualization: 'graph'
    },
    {
      title: 'Island Hydration Strategy',
      query: 'sum by (strategy) (island_hydration_time_count)',
      visualization: 'pie'
    },
    {
      title: 'Federation Cache Efficiency',
      query: 'federation_cache_hit_rate',
      visualization: 'gauge'
    }
  ]
};
